      "source": "farmington/statement_of_basis.pdf",
      "locator": "Page 19, Section: fact_sheet",
      "exact_span": "No variance requests have been received.",
      "affected_purpose": "A,B",
      "computation_change_reason": "Whether this statement establishes that no variance-modified effluent limits or variance-linked monitoring conditions apply to the permit, versus merely reporting administrative status at fact-sheet issuance, could change applicable limit selection and whether variance-dependent monitoring requirements are in scope."
    },
    {
      "source": "farmington/statement_of_basis.pdf",
      "locator": "Page 19, Section: fact_sheet",
      "exact_span": "The permit is in the process of certification by the State agency following regulations promulgated at 40 CFR §124.53.",
      "affected_purpose": "A,B,C",
      "computation_change_reason": "Whether proposed permit conditions are enforceable during FY2025 while certification is still pending affects which numeric limits and monitoring obligations are treated as operative, and whether absent monitoring results reflect missing required evidence versus monitoring not yet required because permit conditions are not fully effective."
    },
    {
      "source": "farmington/statement_of_basis.pdf",
      "locator": "Page 19, Section: fact_sheet",
      "exact_span": "New Mexico State Standards for Interstate and Intrastate Surface Water, 20.6.4 NMAC, effective September 12, 2018.",
      "affected_purpose": "A",
      "computation_change_reason": "Whether and how these cited state water quality standards translate into permit effluent limitations for covered parameters could change which enforceable numeric discharge limits are selected for compliance comparison."
    },
